const cfg = $input.first().json;
const githubRepo = String(cfg.githubRepo || '').trim();
if (!/^[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9_.-]{1,100}$/.test(githubRepo)) {
  throw new Error('Config.githubRepo must be owner/repo');
}
const [owner, repo] = githubRepo.split('/');
const language = String(cfg.language || 'EN').toUpperCase();
if (!['EN', 'FR'].includes(language)) throw new Error('Config.language must be EN or FR');
const until = new Date();
const since = new Date(until.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{ json: { ...cfg, githubRepo, language, owner, repo, since: since.toISOString(), until: until.toISOString() } }];

parameters.jsonBody:
={{ JSON.stringify({
  query: "query WeeklyActivity($owner: String!, $repo: String!, $since: GitTimestamp!, $until: GitTimestamp!, $issueQuery: String!, $prQuery: String!, $commitCursor: String, $issueCursor: String, $prCursor: String, $skipCommits: Boolean!, $skipIssues: Boolean!, $skipPrs: Boolean!) {
  repository(owner: $owner, name: $repo) {
    defaultBranchRef { target { ... on Commit {
      history(first: 100, since: $since, until: $until, after: $commitCursor) @skip(if: $skipCommits) {
        nodes { oid messageHeadline committedDate url author { name user { login } } }
        pageInfo { endCursor hasNextPage }
      }
    } } }
  }
  closedIssues: search(query: $issueQuery, type: ISSUE, first: 100, after: $issueCursor) @skip(if: $skipIssues) {
    issueCount pageInfo { endCursor hasNextPage }
    nodes { ... on Issue { number title url closedAt author { login } } }
  }
  mergedPullRequests: search(query: $prQuery, type: ISSUE, first: 100, after: $prCursor) @skip(if: $skipPrs) {
    issueCount pageInfo { endCursor hasNextPage }
    nodes { ... on PullRequest { number title url mergedAt author { login } } }
  }
}",
  variables: {
    owner: $json.owner, repo: $json.repo, since: $json.since, until: $json.until,
    issueQuery: `repo:${$json.githubRepo} is:issue is:closed closed:${$json.since}..${$json.until}`,
    prQuery: `repo:${$json.githubRepo} is:pr is:merged merged:${$json.since}..${$json.until}`,
    commitCursor: null, issueCursor: null, prCursor: null,
    skipCommits: false, skipIssues: false, skipPrs: false
  }
}) }}

parameters.value:
={{ (() => {
  const v = $request.body.variables;
  const d = $response.body.data || {};
  const commits = d.repository?.defaultBranchRef?.target?.history?.pageInfo;
  const issues = d.closedIssues?.pageInfo;
  const prs = d.mergedPullRequests?.pageInfo;
  return { ...v,
    commitCursor: commits?.endCursor ?? v.commitCursor,
    issueCursor: issues?.endCursor ?? v.issueCursor,
    prCursor: prs?.endCursor ?? v.prCursor,
    skipCommits: v.skipCommits || !commits?.hasNextPage,
    skipIssues: v.skipIssues || !issues?.hasNextPage,
    skipPrs: v.skipPrs || !prs?.hasNextPage
  };
})() }}

