const cfg = $('Build 7-Day Window').first().json;
const sinceMs = Date.parse(cfg.since), untilMs = Date.parse(cfg.until);
const commitsById = new Map(), issuesById = new Map(), prsById = new Map();
const pages = $input.all();
for (const { json: body } of pages) {
  if (body.errors?.length) throw new Error(`GitHub GraphQL: ${body.errors.map(e => e.message).join('; ')}`);
  const d = body.data;
  if (!d?.repository) throw new Error('GitHub repository was not found or is not accessible');
  if (d.closedIssues?.issueCount > 1000 || d.mergedPullRequests?.issueCount > 1000) {
    throw new Error('GitHub search exceeds its 1000-result limit; refusing an incomplete summary');
  }
  for (const c of d.repository.defaultBranchRef?.target?.history?.nodes ?? []) commitsById.set(c.oid, c);
  for (const i of d.closedIssues?.nodes ?? []) if (i.number) issuesById.set(i.number, i);
  for (const pr of d.mergedPullRequests?.nodes ?? []) if (pr.number) prsById.set(pr.number, pr);
}
const last = pages.at(-1)?.json.data;
if ([last?.repository?.defaultBranchRef?.target?.history, last?.closedIssues, last?.mergedPullRequests].some(c => c?.pageInfo?.hasNextPage)) {
  throw new Error('GitHub pagination did not complete; refusing an incomplete summary');
}
const inWindow = value => Number.isFinite(Date.parse(value)) && Date.parse(value) >= sinceMs && Date.parse(value) <= untilMs;
const commits = [...commitsById.values()].filter(x => inWindow(x.committedDate));
const closedIssues = [...issuesById.values()].filter(x => inWindow(x.closedAt));
const mergedPullRequests = [...prsById.values()].filter(x => inWindow(x.mergedAt));

const author = (x) => x?.author?.login || x?.author?.user?.login || x?.author?.name || 'unknown';

const activity = {
  repository: cfg.githubRepo,
  since: cfg.since,
  until: cfg.until,
  commits: commits.map(x => ({ sha: x.oid.slice(0, 8), title: x.messageHeadline, author: author(x), committedAt: x.committedDate, url: x.url })),
  closedIssues: closedIssues.map(x => ({ number: x.number, title: x.title, author: author(x), closedAt: x.closedAt, url: x.url })),
  mergedPullRequests: mergedPullRequests.map(x => ({ number: x.number, title: x.title, author: author(x), mergedAt: x.mergedAt, url: x.url })),
};

const languageInstruction = cfg.language === 'FR'
  ? 'Écris le résumé final en français naturel et professionnel.'
  : 'Write the final summary in natural, professional English.';

const commitsText = activity.commits.length ? activity.commits.map(x => `- ${x.sha}: ${x.title} — ${x.author}`).join('\n') : '- None';
const issuesText = activity.closedIssues.length ? activity.closedIssues.map(x => `- #${x.number}: ${x.title} — ${x.author}`).join('\n') : '- None';
const prsText = activity.mergedPullRequests.length ? activity.mergedPullRequests.map(x => `- #${x.number}: ${x.title} — ${x.author}`).join('\n') : '- None';

const prompt = `${languageInstruction}

Create a concise weekly engineering narrative for ${cfg.githubRepo}, covering ${cfg.since} through ${cfg.until}.
Do not invent activity. Explain the main themes, notable progress, maintenance/bug-fix work, and what the mix of commits/issues/PRs suggests.
Start with a one-sentence executive summary, then use short Markdown sections:
- Highlights
- Merged pull requests
- Closed issues
- Commit themes
End with a compact activity line containing the exact counts.

Commits (${activity.commits.length}):
${commitsText}

Merged pull requests (${activity.mergedPullRequests.length}):
${prsText}

Closed issues (${activity.closedIssues.length}):
${issuesText}`;

return [{ json: { ...cfg, activity, prompt } }];

const response = $input.first().json;
const cfg = $('Build Claude Prompt').first().json;
const summary = response.content?.filter(part => part.type === 'text').map(part => part.text).join('\n').trim();

if (response.stop_reason === 'max_tokens') throw new Error('Anthropic response was truncated; refusing delivery');
if (!summary) {
  throw new Error('Anthropic response contained no text summary');
}

return [{
  json: {
    repository: cfg.githubRepo,
    language: cfg.language,
    summary,
    slackText: `*Weekly dev summary — ${cfg.githubRepo}*\n${summary}`,
    counts: {
      commits: cfg.activity.commits.length,
      mergedPullRequests: cfg.activity.mergedPullRequests.length,
      closedIssues: cfg.activity.closedIssues.length,
    },
  },
}];
